         outline: 2px solid Highlight;
         outline-offset: 2px;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#maincontent">Skip to main content</a>
   <div id="app"></div>

   <script>
     const PageShell = ({ children }) => `
       <main id="maincontent" tabindex="-1">
         <div class="page-shell">
           <section class="hero" aria-labelledby="page-title">
             ${children}
           </section>
         </div>
       </main>
     `;

     const IntroBlock = () => `
       <div>
         <p class="eyebrow">Customer preferences</p>
         <h1 id="page-title">Choose how you want to stay in the loop.</h1>
         <p>
           Set one notification channel for product updates, account activity, and
           important reminders. You can change this preference any time.
         </p>
       </div>
     `;

     const NotificationPreferenceField = () => `
       <div class="form-field">
         <fieldset id="notification-group" aria-describedby="notification-hint">
           <legend>
             How do you prefer to receive notifications?
             <span class="required-mark" aria-hidden="true">*</span>
           </legend>
           <p class="field-help" id="notification-hint">Choose one option before submitting your preference.</p>
           <div class="choice-list">
             <label class="choice-card" for="preference-email">
               <input id="preference-email" type="radio" name="notificationPreference" value="Email" required>
               <span class="choice-text">Email</span>
             </label>
             <label class="choice-card" for="preference-sms">
               <input id="preference-sms" type="radio" name="notificationPreference" value="SMS" required>
               <span class="choice-text">SMS</span>
             </label>
             <label class="choice-card" for="preference-push">
               <input id="preference-push" type="radio" name="notificationPreference" value="Push Notifications" required>
               <span class="choice-text">Push Notifications</span>
             </label>
           </div>
           <p class="field-error" id="notification-error" hidden></p>
         </fieldset>
       </div>
     `;

     const PreferenceForm = () => `
       <section class="form-card" aria-labelledby="form-title">
         <div>
           <h2 id="form-title">Notification settings</h2>
           <p class="field-meta">Required fields are marked with <span class="required-mark" aria-hidden="true">*</span>.</p>
         </div>
         <form id="notification-form" novalidate>
           ${NotificationPreferenceField()}
           <div class="actions">
             <button class="button-primary" type="submit">Save preference</button>
             <p class="status-message" id="form-status" role="status" aria-live="polite"></p>
           </div>
         </form>
       </section>
     `;

     const App = () => PageShell({
       children: `
         ${IntroBlock()}
         ${PreferenceForm()}
       `
     });

     const appRoot = document.getElementById("app");
     appRoot.innerHTML = App();

     const form = document.getElementById("notification-form");
     const radios = Array.from(form.elements.namedItem("notificationPreference"));
     const errorMessage = document.getElementById("notification-error");
     const statusMessage = document.getElementById("form-status");
     const fieldset = document.getElementById("notification-group");

     const setRadioValidityState = (isInvalid) => {
       fieldset.setAttribute(
         "aria-describedby",
         isInvalid ? "notification-hint notification-error" : "notification-hint"
       );

       radios.forEach((radio) => {
         if (isInvalid) {
           radio.setAttribute("aria-invalid", "true");
         } else {
           radio.removeAttribute("aria-invalid");
         }
       });
     };

     const clearMessages = () => {
       errorMessage.hidden = true;
       errorMessage.textContent = "";
       statusMessage.textContent = "";
       setRadioValidityState(false);
     };

     form.addEventListener("submit", (event) => {
       const selectedRadio = radios.find((radio) => radio.checked);

       if (!selectedRadio) {
         event.preventDefault();
         errorMessage.hidden = false;
         errorMessage.textContent = "Error: Select how you prefer to receive notifications.";
         statusMessage.textContent = "";
         setRadioValidityState(true);
         radios[0].focus();
         return;
       }

       event.preventDefault();
       clearMessages();
       statusMessage.textContent = `Preference saved: ${selectedRadio.value}.`;
     });

     radios.forEach((radio) => {
       radio.addEventListener("change", () => {
         clearMessages();
       });
     });
   </script>
 </body>
 </html>

')
